import {DocumentStore} from '../../src/model';
import {saveObject,presetDraft,objectGraphic,objectDraft} from '../../src/objects';
import {saveVector,saveSeparation,vectorGraphic} from '../../src/physics';
import type {Expression} from '../../src/semantics';
export const ref=(id:string):Expression=>({type:'reference',id});
const times=(a:Expression,b:Expression):Expression=>({type:'binary',op:'*',left:a,right:b});
const unknown={state:'unknown' as const,unit:'N'};
export function scenarios(){
 const result:Record<string,DocumentStore>={};
 const object=(s:DocumentStore,name:string,properties={})=>saveObject(s,{name,representation:'circle',showName:true,showProperties:true,properties});
 const prop=(s:DocumentStore,id:string,key:string)=>s.document.semantics.objects.find(o=>o.id===id)!.properties![key];
 {const s=new DocumentStore(),planet=saveObject(s,presetDraft('planetSurface')),book=object(s,'Book',{mass:{symbol:'m_7',state:'unknown',unit:'kg'}});s.update(objectGraphic(s,planet)!.id,{visible:true});saveVector(s,{kind:'force',interactionType:'gravitational',sourceId:planet,targetId:book,magnitude:{state:'expression',unit:'N',expression:times(ref(prop(s,book,'mass')),ref(prop(s,planet,'gravity')))}});result.A=s;}
 {const s=new DocumentStore(),a=object(s,'Earth',{mass:{symbol:'M',state:'known',unit:'kg',value:5.97e24}}),b=object(s,'Emu',{mass:{symbol:'m',state:'unknown',unit:'kg'}}),sep=saveSeparation(s,{fromId:a,toId:b,magnitude:{state:'known',unit:'m',value:6.4e6}});const rid=s.document.semantics.vectors.find(v=>v.id===sep)!.variableId;saveVector(s,{kind:'force',interactionType:'gravitational',sourceId:a,targetId:b,separationId:sep,magnitude:{state:'expression',unit:'N',expression:{type:'binary',op:'/',left:times(times(ref('constant:G'),ref(prop(s,a,'mass'))),ref(prop(s,b,'mass'))),right:{type:'binary',op:'^',left:ref(rid),right:{type:'number',value:2}}}}});result.B=s;}
 {const s=new DocumentStore(),a=object(s,'Source',{charge:{symbol:'Q',state:'known',unit:'C',value:-1e-6}}),p=saveObject(s,{...presetDraft('spatialPoint'),name:'P',properties:{charge:{symbol:'q_p',state:'unknown',unit:'C'}}}),sep=saveSeparation(s,{fromId:a,toId:p,magnitude:{state:'unknown',unit:'m'}});saveVector(s,{kind:'field',interactionType:'electric',sourceId:a,targetId:p,separationId:sep,magnitude:{state:'unknown',unit:'N/C'}});const plate=saveObject(s,{...presetDraft('chargedPlate'),polarity:'negative',properties:{surfaceChargeDensity:{symbol:'\\sigma',state:'known',unit:'C/m^2',value:-1e-6}}}),p2=saveObject(s,{...presetDraft('spatialPoint'),name:'P2'});saveVector(s,{kind:'field',interactionType:'electric',sourceId:plate,targetId:p2,magnitude:{state:'unknown',unit:'N/C'}});result.C=s;}
 {const s=new DocumentStore(),book=object(s,'Book'),table=saveObject(s,{name:'Table',representation:'rectangle',showName:true,showProperties:true});saveVector(s,{kind:'force',interactionType:'contact',contactType:'ordinary',sourceId:table,targetId:book,friction:'kinetic',coefficient:{symbol:'\\mu_k',state:'known',unit:'1',value:.3},resultantVisible:true,magnitude:unknown,frictionMagnitude:unknown,angle:-60,length:100,frictionLength:60});result.D=s;}
 {const s=new DocumentStore(),spring=saveObject(s,{...presetDraft('spring'),properties:{springConstant:{symbol:'k',state:'unknown',unit:'N/m'},extension:{symbol:'\\Delta x',state:'known',unit:'m',value:-.1}}}),block=object(s,'Block'),cable=saveObject(s,presetDraft('cable'));saveVector(s,{kind:'force',interactionType:'contact',contactType:'spring',sourceId:spring,targetId:block,magnitude:{state:'expression',unit:'N',expression:{type:'unary',op:'abs',operand:times(ref(prop(s,spring,'springConstant')),ref(prop(s,spring,'extension')))}}});saveVector(s,{kind:'force',interactionType:'contact',contactType:'cable',sourceId:cable,targetId:block,magnitude:unknown});result.E=s;}
 {const s=new DocumentStore(),water=saveObject(s,presetDraft('fluid')),rock=object(s,'Rock'),planet=saveObject(s,presetDraft('planetSurface'));const id=saveVector(s,{kind:'force',interactionType:'buoyant',sourceId:water,targetId:rock,volume:{symbol:'V_{disp}',state:'known',unit:'m^3',value:.002},magnitude:unknown});const i=s.document.semantics.interactions.find(i=>i.id===s.document.semantics.vectors.find(v=>v.id===id)!.interactionId)!;saveVector(s,{id,kind:'force',interactionType:'buoyant',sourceId:water,targetId:rock,volume:{symbol:'V_{disp}',state:'known',unit:'m^3',value:.002},magnitude:{state:'expression',unit:'N',expression:times(times(ref(prop(s,water,'density')),ref(i.properties!.volume)),ref(prop(s,planet,'gravity')))}});result.F=s;}
 for(const [key,s]of Object.entries(result)){s.document.metadata.title=`Scenario ${key}`;s.document.semantics.objects.forEach((o,index)=>{const g=objectGraphic(s,o.id)!;if(!['surface'].includes(g.kind))s.update(g.id,{x:140+(index%3)*220,y:150+Math.floor(index/3)*180});});}
 return result;
}
